function GachaponCacheConfirm:Refresh()
    local cnt = #self._tabResult
    for i = 1, cnt do
        local trans = self.HeadNode:GetChild(i - 1)
        local behavior = GetLuaBehaviour(trans.gameObject, headPath)
        if isNull(behavior.Env) then
            behavior:Init()
        end
        local dojo = CardUtils.GenerateCustomById(self._tabResult[i].goodsId)
        behavior.Env:FreshNode(dojo)
        behavior.Env:SetStarStatus(false)
        behavior.Env:SetLvStatus(false)
        behavior.Env:SetRookieStatus(KCookie.Get("DRAW_CARD_ROOKIE_VIEW") == true)
        --behavior.Env:SetCallBack(function(id, index)
        --    GachaponUtils.OpenDetail(id)
        --end)
    end
end

